function findMaximumScore(nums) {
  const last = nums.length - 1;
  let score = 0;
  let from = 0;

  for (let to = 1; to <= last; to++) {
    if (nums[to] > nums[from] || to === last) {
      score += (to - from) * nums[from];
      from = to;
    }
  }
  return score;
}

