function findMaximumScore(nums) {
  // best[j] is the highest score of any jump sequence that ends on index j.
  const best = new Array(nums.length).fill(-Infinity);
  best[0] = 0;
  for (let j = 1; j < nums.length; j++)
    for (let i = 0; i < j; i++)
      best[j] = Math.max(best[j], best[i] + (j - i) * nums[i]);
  return best[nums.length - 1];
}

