function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = int(1, 8);
    const top = rand() < 0.75 ? int(1, 6) : 100000;
    return [Array.from({ length: n }, () => int(1, top))];
  }
  const n = int(1500, 2000);
  const shape = Math.floor(rand() * 3);
  const nums = Array.from({ length: n }, (_, i) => {
    if (shape === 0) return int(1, 100000);
    // Slowly rising values with noise: many new records, so many jumps.
    if (shape === 1) return Math.min(100000, 1 + i * 40 + int(0, 2000));
    // Falling values: the first element stays the best rate for the whole trip.
    return Math.max(1, 100000 - i * 50 - int(0, 100));
  });
  return [nums];
}
